fn without_nulls(patch: &Value, depth: u32) -> Value {
    let Value::Object(fields) = patch else {
        return patch.clone();
    };
    if depth >= MAX_PATCH_DEPTH {
        return patch.clone();
    }
    Value::Object(
        fields
            .iter()
            .filter(|(_, value)| !value.is_null())
            .map(|(key, value)| (key.clone(), without_nulls(value, depth + 1)))
            .collect(),
    )
}

